#!/usr/bin/env bash
set -euo pipefail
project_directory="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)"
environment_path="$project_directory/.env"
if [[ -e "$environment_path" ]]; then
  printf '%s\n' '.env already exists; no values were changed.'
  exit 0
fi
command -v openssl >/dev/null || { printf '%s\n' 'Install openssl to generate random secrets.' >&2; exit 1; }
umask 077
database_password="$(openssl rand -hex 32)"
jwt_secret="$(openssl rand -hex 48)"
admin_password="$(openssl rand -hex 24)"
set -o noclobber
cat > "$environment_path" <<EOF
# Local credentials generated by init-env.sh. Do not commit or share this file.
POSTGRES_DB=ktor_realtime
POSTGRES_USER=realtime_app
POSTGRES_PASSWORD=$database_password
JWT_SECRET=$jwt_secret
ADMIN_USERNAME=admin
ADMIN_PASSWORD=$admin_password
APP_PORT=8091
PG_PORT=55435
EOF
printf '%s\n' 'Created .env with random secrets. The initial admin password is in ADMIN_PASSWORD.'
